// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Synth} from "../src/Synth.sol";

contract InvMutTest is Test {
    Synth c;

    function setUp() public {
        c = new Synth(address(this), address(new __InvMutHandleStub()));
    }

    function testFuzz_property(address spender, uint256 initial, uint256 addedValue) public {
        vm.assume(spender != address(0));
        addedValue = bound(addedValue, 1, type(uint128).max);
        initial = bound(initial, 0, type(uint128).max);

        c.approve(spender, initial);
        uint256 beforeAllowance = c.allowance(address(this), spender);

        bool ok = true;
        try c.increaseAllowance(spender, addedValue) returns (bool) {
        } catch {
            ok = false;
        }

        uint256 afterAllowance = c.allowance(address(this), spender);
        assertTrue(ok && afterAllowance == beforeAllowance + addedValue, "increaseAllowance must increase allowance by addedValue");
    }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
